        {
            put("final", new HashMap<String, String>() {

                {
                    put("a", "true");
                }
            });
        }
    })));
    try {
        controller.updateClusters(Collections.singleton(cr), new HashMap<String, String>());
        Assert.fail("Expect failure when creating a config that exists");
    } catch (AmbariException e) {
        // expected
    }
}

