    coreSiteProperties.put("fs.defaultFS", "hdfs://" + expectedNameService);
    // configure the hbase rootdir to use the nameservice URL
    hbaseSiteProperties.put("hbase.rootdir", "hdfs://" + expectedNameService + "/hbase/test/root/dir");
    // configure the hbase rootdir to use the nameservice URL
