    verify(provider);
    reset(provider);
    expect(provider.checkPropertyIds(capture(propertiesCapture))).andReturn(Collections.<String>emptySet()).anyTimes();
    replay(provider);
    // ---
    PredicateHelper.visit(PREDICATE_15, visitor);
