/**
 * Verify that know {@link NotificationDispatcher}s are registered via the
 * Guice {@link Module} and that they singletons.
 *
 * @throws Exception
 */
@Test
public void testDispatchFactoryRegistration() throws Exception {
    String sourceResourceDirectory = "src" + File.separator + "test" + File.separator + "resources";
    Integer snmpPort = 30111;
    Properties properties = new Properties();
    properties.setProperty(Configuration.SERVER_PERSISTENCE_TYPE.getKey(), "in-memory");
    properties.setProperty(Configuration.OS_VERSION.getKey(), "centos6");
    properties.setProperty(Configuration.SHARED_RESOURCES_DIR.getKey(), sourceResourceDirectory);
    properties.setProperty(Configuration.ALERTS_SNMP_DISPATCH_UDP_PORT.getKey(), snmpPort.toString());
    Injector injector = Guice.createInjector(new AuditLoggerModule(), new ControllerModule(properties));
    DispatchFactory dispatchFactory = injector.getInstance(DispatchFactory.class);
    DispatchFactory dispatchFactory2 = injector.getInstance(DispatchFactory.class);
    // verify singleton
    Assert.assertEquals(dispatchFactory, dispatchFactory2);
    EmailDispatcher emailDispatcher = injector.getInstance(EmailDispatcher.class);
    EmailDispatcher emailDispatcher2 = (EmailDispatcher) dispatchFactory.getDispatcher(emailDispatcher.getType());
    Assert.assertNotNull(emailDispatcher);
    Assert.assertNotNull(emailDispatcher2);
    // verify singleton
    Assert.assertEquals(emailDispatcher, emailDispatcher2);
    SNMPDispatcher snmpDispatcher = injector.getInstance(SNMPDispatcher.class);
    SNMPDispatcher snmpDispatcher2 = (SNMPDispatcher) dispatchFactory.getDispatcher(snmpDispatcher.getType());
    Assert.assertNotNull(snmpDispatcher);
    Assert.assertEquals(snmpDispatcher.getPort(), snmpPort);
    Assert.assertNotNull(snmpDispatcher2);
    Assert.assertEquals(snmpDispatcher2.getPort(), snmpPort);
    // verify singleton
    Assert.assertEquals(snmpDispatcher, snmpDispatcher2);
}

@Test
public void canBeCommittedIfExceptionsToBeRolledBackOnIsEmpty() {
    Transactional transactional = createNiceMock(Transactional.class);
    EntityTransaction transaction = createStrictMock(EntityTransaction.class);
    expect(transaction.getRollbackOnly()).andReturn(false);
    expect(transactional.rollbackOn()).andReturn(asArray());
    replayAll();
    boolean canCommit = rollbackIfNecessary(transactional, new RuntimeException(), transaction);
    Assert.assertTrue("Should be allowed to commit, since rollbackOn clause is empty", canCommit);
    verifyAll();
}

@Test
public void canBeCommittedIfUnknownExceptionThrown() {
    Transactional transactional = createNiceMock(Transactional.class);
    EntityTransaction transaction = createStrictMock(EntityTransaction.class);
    expect(transaction.getRollbackOnly()).andReturn(false);
    expect(transactional.rollbackOn()).andReturn(asArray(IllegalArgumentException.class));
    replayAll();
    boolean canCommit = rollbackIfNecessary(transactional, new RuntimeException(), transaction);
    Assert.assertTrue("Should be allowed to commit, exception thrown does not match rollbackOn clause", canCommit);
    verifyAll();
}

@Test
public void rolledBackForKnownException() {
    Transactional transactional = createNiceMock(Transactional.class);
    EntityTransaction transaction = createStrictMock(EntityTransaction.class);
    expect(transaction.getRollbackOnly()).andReturn(false);
    expect(transactional.rollbackOn()).andReturn(asArray(NullPointerException.class, IllegalArgumentException.class));
    expect(transactional.ignore()).andReturn(asArray());
    transaction.rollback();
    replayAll();
    boolean canCommit = rollbackIfNecessary(transactional, new IllegalArgumentException("rolling back"), transaction);
    Assert.assertFalse("Should be rolled back, since exception matches rollbackOn clause", canCommit);
    verifyAll();
}

@Test
public void rolledBackForSubclassOfKnownException() {
    Transactional transactional = createNiceMock(Transactional.class);
    EntityTransaction transaction = createStrictMock(EntityTransaction.class);
    expect(transaction.getRollbackOnly()).andReturn(false);
    expect(transactional.rollbackOn()).andReturn(asArray(RuntimeException.class));
    expect(transactional.ignore()).andReturn(asArray());
    transaction.rollback();
    replayAll();
    boolean canCommit = rollbackIfNecessary(transactional, new IllegalArgumentException("rolling back"), transaction);
    Assert.assertFalse("Should be rolled back, since exception is subclass of the one in rollbackOn clause", canCommit);
    verifyAll();
}

