    Assert.assertEquals("admin_password", handler.getResponse("password"));
    Assert.assertFalse(handler.done());
    Assert.assertEquals("user_password", handler.getResponse("password"));
    Assert.assertFalse(handler.done());
    Assert.assertEquals("user_password", handler.getResponse("password"));
    Assert.assertTrue(handler.done());
}

