    List<ServiceConfigVersionResponse> configVersionsAfter = cluster.getServiceConfigVersions();
    Assert.assertFalse(configVersionsAfter.isEmpty());
    assertTrue(configVersionsAfter.size() - configVersionsBefore.size() >= 1);
}

