    for (String hostName : hostNames) {
        serviceComponentHosts.add(createNewServiceComponentHost("HDFS", "NAMENODE", hostName));
        serviceComponentHosts.add(createNewServiceComponentHost("HDFS", "DATANODE", hostName));
