@Test
public void testConfigUpgradeDefinitionParsing() throws Exception {
    ConfigUpgradePack cup = ambariMetaInfo.getConfigUpgradePack("HDP", "2.1.1");
    Map<String, ConfigUpgradeChangeDefinition> changesByID = cup.enumerateConfigChangesByID();
    ConfigUpgradeChangeDefinition hdp_2_1_1_nm_pre_upgrade = changesByID.get("hdp_2_1_1_nm_pre_upgrade");
    assertEquals("core-site", hdp_2_1_1_nm_pre_upgrade.getConfigType());
    assertEquals(4, hdp_2_1_1_nm_pre_upgrade.getTransfers().size());
    /*
            <transfer operation="COPY" from-key="copy-key" to-key="copy-key-to" />
            <transfer operation="COPY" from-type="my-site" from-key="my-copy-key" to-key="my-copy-key-to" />
            <transfer operation="MOVE" from-key="move-key" to-key="move-key-to" />
            <transfer operation="DELETE" delete-key="delete-key">
              <keep-key>important-key</keep-key>
            </transfer>
    */
    ConfigUpgradeChangeDefinition.Transfer t1 = hdp_2_1_1_nm_pre_upgrade.getTransfers().get(0);
    assertEquals(TransferOperation.COPY, t1.operation);
    assertEquals("copy-key", t1.fromKey);
    assertEquals("copy-key-to", t1.toKey);
    ConfigUpgradeChangeDefinition.Transfer t2 = hdp_2_1_1_nm_pre_upgrade.getTransfers().get(1);
    assertEquals(TransferOperation.COPY, t2.operation);
    assertEquals("my-site", t2.fromType);
    assertEquals("my-copy-key", t2.fromKey);
    assertEquals("my-copy-key-to", t2.toKey);
    assertTrue(t2.keepKeys.isEmpty());
    ConfigUpgradeChangeDefinition.Transfer t3 = hdp_2_1_1_nm_pre_upgrade.getTransfers().get(2);
    assertEquals(TransferOperation.MOVE, t3.operation);
    assertEquals("move-key", t3.fromKey);
    assertEquals("move-key-to", t3.toKey);
    ConfigUpgradeChangeDefinition.Transfer t4 = hdp_2_1_1_nm_pre_upgrade.getTransfers().get(3);
    assertEquals(TransferOperation.DELETE, t4.operation);
    assertEquals("delete-key", t4.deleteKey);
    assertNull(t4.toKey);
    assertTrue(t4.preserveEdits);
    assertEquals(1, t4.keepKeys.size());
    assertEquals("important-key", t4.keepKeys.get(0));
}

/**
 * Tests that every ID specified in an upgrade pack actually exists in the
 * created {@link ConfigUpgradePack}.
 *
 * @throws Exception
 */
@Test
public void testConfigurationDefinitionsExist() throws Exception {
    Collection<StackInfo> stacks = ambariMetaInfo.getStacks();
    Assert.assertFalse(stacks.isEmpty());
    for (StackInfo stack : stacks) {
        if (!stack.isActive()) {
            LOG.info("Skipping configuration validity test for {}", new StackId(stack));
            continue;
        }
        Map<String, UpgradePack> upgradePacks = ambariMetaInfo.getUpgradePacks(stack.getName(), stack.getVersion());
        for (String key : upgradePacks.keySet()) {
            UpgradePack upgradePack = upgradePacks.get(key);
            StackId sourceStack = new StackId(stack);
            ConfigUpgradePack configUpgradePack = ConfigurationPackBuilder.build(upgradePack, sourceStack);
            // do configure tasks in the group section
            List<Grouping> groups = upgradePack.getGroups(Direction.UPGRADE);
            for (Grouping group : groups) {
                if (group instanceof ClusterGrouping) {
                    ClusterGrouping clusterGrouping = (ClusterGrouping) group;
                    if (null != clusterGrouping.executionStages) {
                        for (ExecuteStage executionStage : clusterGrouping.executionStages) {
                            if (executionStage.task.getType() == Type.CONFIGURE) {
                                ConfigureTask configureTask = (ConfigureTask) executionStage.task;
                                assertIdDefinitionExists(configureTask.id, configUpgradePack, upgradePack, sourceStack);
                            }
                        }
                    }
                }
            }
            // do tasks in the "processing" section
            Map<String, Map<String, ProcessingComponent>> tasks = upgradePack.getTasks();
            for (Map<String, ProcessingComponent> value : tasks.values()) {
                for (ProcessingComponent processingComponent : value.values()) {
                    if (null != processingComponent.preTasks) {
                        for (Task preTask : processingComponent.preTasks) {
                            if (preTask.getType() == Type.CONFIGURE) {
                                ConfigureTask configureTask = (ConfigureTask) preTask;
                                assertIdDefinitionExists(configureTask.id, configUpgradePack, upgradePack, sourceStack);
                            }
                        }
                        if (null != processingComponent.tasks) {
                            for (Task task : processingComponent.tasks) {
                                if (task.getType() == Type.CONFIGURE) {
                                    ConfigureTask configureTask = (ConfigureTask) task;
                                    assertIdDefinitionExists(configureTask.id, configUpgradePack, upgradePack, sourceStack);
                                }
                            }
                        }
                        if (null != processingComponent.postTasks) {
                            for (Task postTask : processingComponent.postTasks) {
                                if (postTask.getType() == Type.CONFIGURE) {
                                    ConfigureTask configureTask = (ConfigureTask) postTask;
                                    assertIdDefinitionExists(configureTask.id, configUpgradePack, upgradePack, sourceStack);
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    // make sure we actually checked a bunch of configs :)
    Assert.assertTrue(validatedConfigCount > 100);
}

@Test
@SuppressWarnings("unchecked")
public void testValidateConfigUpgradePacks() throws Exception {
    IOFileFilter filter = new IOFileFilter() {

        @Override
        public boolean accept(File dir, String name) {
            return false;
        }

        @Override
        public boolean accept(File file) {
            // file has the folder named 'upgrades', ends with '.xml' and is NOT
            // 'config-upgrade.xml'
            if (file.getAbsolutePath().contains("upgrades") && file.getAbsolutePath().endsWith("config-upgrade.xml")) {
                return true;
            }
            return false;
        }
    };
    List<File> files = new ArrayList<>();
    files.addAll(FileUtils.listFiles(new File("src/main/resources/stacks"), filter, FileFilterUtils.directoryFileFilter()));
    files.addAll(FileUtils.listFiles(new File("src/test/resources/stacks"), filter, FileFilterUtils.directoryFileFilter()));
    files.addAll(FileUtils.listFiles(new File("src/test/resources/stacks_with_upgrade_cycle"), filter, FileFilterUtils.directoryFileFilter()));
    ModuleFileUnmarshaller unmarshaller = new ModuleFileUnmarshaller();
    int filesTestedCount = 0;
    for (File file : files) {
        String fileContent = FileUtils.readFileToString(file, "UTF-8");
        // these things must be in upgrade packs for them to work anyway
        if (fileContent.contains("<upgrade-config-changes") && fileContent.contains("xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"")) {
            if (!fileContent.contains("xsi:noNamespaceSchemaLocation=\"upgrade-config.xsd\"")) {
                String msg = String.format("File %s appears to be a config upgrade pack, but does not define 'upgrade-config.xsd' as its schema", file.getAbsolutePath());
                Assert.fail(msg);
            } else {
                filesTestedCount++;
                unmarshaller.unmarshal(ConfigUpgradePack.class, file, true);
            }
        }
    }
    Assert.assertTrue("This test didn't appear to do any work which could indicate that it failed to find files to validate", filesTestedCount > 5);
}

