            Assert.assertNotNull(entityHostComponentDesiredState);
            Assert.assertEquals(state, entityHostComponentDesiredState.getSecurityState());
        } catch (AmbariException e) {
            Assert.assertFalse(state.isEndpoint());
        }
    }
}

