    cpds2.setPassword("password");
    expectLastCall().once();
    cpds2.setInitialPoolSize(0);
    expectLastCall().once();
    cpds2.setMinPoolSize(0);
    expectLastCall().once();
    cpds2.setMaxPoolSize(1);
    expectLastCall().once();
    cpds2.setMaxIdleTime(600);
    expectLastCall().once();
    cpds2.setAcquireRetryAttempts(5);
    expectLastCall().once();
    cpds2.setAcquireRetryDelay(1000);
